CREATE OR REPLACE FUNCTION private.phase4_enforce_assignment_order_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid text := (select auth.jwt()->>'sub');
  v_is_staff boolean := private.is_izytel_phase4_staff();
  v_partner_id uuid;
  v_reason text;
  v_plan public.phase4_assignment_plans%rowtype;
  v_refused text[];
  v_refused_partners uuid[];
  v_next_agent text;
  v_next_name text;
  v_next_partner uuid;
  v_next_partner_name text;
  v_history_id uuid;
begin
  if v_is_staff then
    new.updated_at := now();
    return new;
  end if;

  if not public.is_izytel_firebase_jwt()
     or v_uid is null
     or btrim(v_uid)='' then
    raise exception 'AUTH_REQUIRED';
  end if;

  if old.assigned_cabiniste_id is not null then
    select p.id into v_partner_id
    from public.partner_accounts p
    where p.firebase_uid=v_uid
      and p.status='active'
    limit 1;

    if v_partner_id is null
       or old.assigned_cabiniste_id is distinct from v_partner_id then
      raise exception 'CABINISTE_ASSIGNMENT_OWNER_REQUIRED'
        using errcode='42501';
    end if;

    new.order_id := old.order_id;
    new.order_reference := old.order_reference;
    new.network := old.network;
    new.amount := old.amount;
    new.firebase_created_at := old.firebase_created_at;
    new.paid_at := old.paid_at;
    new.created_at := old.created_at;
    new.assigned_by_uid := old.assigned_by_uid;
    new.customer_auth_uid := old.customer_auth_uid;
    new.source := old.source;
    new.client_name := old.client_name;
    new.client_whatsapp_phone := old.client_whatsapp_phone;
    new.beneficiary_phone := old.beneficiary_phone;
    new.operation_type := old.operation_type;
    new.offer_label := old.offer_label;
    new.original_whatsapp_message := old.original_whatsapp_message;
    new.internal_notes := old.internal_notes;
    new.payment_status := old.payment_status;
    new.payment_payer_name := old.payment_payer_name;
    new.payment_reference := old.payment_reference;
    new.payment_confirmed_at := old.payment_confirmed_at;

    if old.assignment_state='assigned'
       and new.assignment_state='accepted' then
      new.assigned_agent_id := null;
      new.assigned_agent_name := null;
      new.assigned_cabiniste_id := old.assigned_cabiniste_id;
      new.assigned_cabiniste_name := old.assigned_cabiniste_name;
      new.assignment_mode := old.assignment_mode;
      new.assigned_at := old.assigned_at;
      new.last_refusal_reason := old.last_refusal_reason;
      new.last_refused_at := old.last_refused_at;
      new.last_refused_agent_id := old.last_refused_agent_id;
      new.last_refused_cabiniste_id := old.last_refused_cabiniste_id;
      new.firebase_assignment_synced_at := old.firebase_assignment_synced_at;
      new.firebase_handoff_at := old.firebase_handoff_at;
      new.order_status := old.order_status;
      new.processing_started_at := old.processing_started_at;
      new.completed_at := old.completed_at;
      new.failure_reason := old.failure_reason;
      new.observation := old.observation;
      new.last_hold_reason := old.last_hold_reason;
      new.last_held_at := old.last_held_at;
      new.last_resumed_at := old.last_resumed_at;
      new.customer_confirmation_status := old.customer_confirmation_status;
      new.customer_confirmation_completed_at := old.customer_confirmation_completed_at;
      new.legacy_state_unresolved := old.legacy_state_unresolved;
      new.updated_at := now();

      select h.id into v_history_id
      from public.phase4_partner_assignment_history h
      where h.order_id=old.order_id
        and h.partner_id=v_partner_id
        and h.status='assigned'
      order by h.assigned_at desc
      limit 1;

      if v_history_id is not null then
        update public.phase4_partner_assignment_history
        set status='accepted',
            accepted_at=now()
        where id=v_history_id;
      end if;

      return new;
    end if;

    if old.assignment_state='assigned'
       and new.assignment_state='refused' then
      v_reason := btrim(coalesce(new.last_refusal_reason,''));
      if char_length(v_reason)<3 or char_length(v_reason)>500 then
        raise exception 'INVALID_REFUSAL_REASON';
      end if;

      select * into v_plan
      from public.phase4_assignment_plans
      where order_id=old.order_id
      for update;

      if not found then
        raise exception 'ASSIGNMENT_PLAN_MISSING';
      end if;

      v_refused_partners := coalesce(
        v_plan.refused_cabiniste_ids,
        '{}'::uuid[]
      );

      if not (v_partner_id=any(v_refused_partners)) then
        v_refused_partners := array_append(
          v_refused_partners,
          v_partner_id
        );
      end if;

      update public.phase4_assignment_plans
      set refused_cabiniste_ids=v_refused_partners,
          updated_at=now()
      where order_id=old.order_id;

      select h.id into v_history_id
      from public.phase4_partner_assignment_history h
      where h.order_id=old.order_id
        and h.partner_id=v_partner_id
        and h.status in ('assigned','accepted')
      order by h.assigned_at desc
      limit 1;

      if v_history_id is not null then
        update public.phase4_partner_assignment_history
        set status='refused',
            refused_at=now(),
            refusal_reason=v_reason,
            accepted_at=null
        where id=v_history_id;
      end if;

      select candidate_id into v_next_partner
      from unnest(
        coalesce(v_plan.candidate_cabiniste_ids,'{}'::uuid[])
      ) with ordinality as c(candidate_id,ord)
      where not (candidate_id=any(v_refused_partners))
        and private.izytel_cabiniste_is_eligible(
          candidate_id,
          old.order_id
        )
      order by ord
      limit 1;

      new.last_refusal_reason := v_reason;
      new.last_refused_at := now();
      new.last_refused_cabiniste_id := v_partner_id;
      new.firebase_assignment_synced_at := null;
      new.firebase_handoff_at := null;
      new.order_status := 'paidReady';
      new.processing_started_at := null;
      new.completed_at := null;
      new.failure_reason := null;
      new.observation := null;
      new.last_hold_reason := null;
      new.last_held_at := null;
      new.last_resumed_at := null;
      new.customer_confirmation_status := 'pending';
      new.customer_confirmation_completed_at := null;
      new.legacy_state_unresolved := false;
      new.assigned_agent_id := null;
      new.assigned_agent_name := null;

      if v_next_partner is null then
        new.assignment_state := 'manual_required';
        new.assigned_cabiniste_id := null;
        new.assigned_cabiniste_name := null;
        new.assignment_mode := null;
        new.assigned_at := null;
      else
        v_next_partner_name := nullif(
          btrim(coalesce(
            v_plan.candidate_cabiniste_names
              ->>v_next_partner::text,
            ''
          )),
          ''
        );

        if v_next_partner_name is null then
          select p.display_name into v_next_partner_name
          from public.partner_accounts p
          where p.id=v_next_partner;
        end if;

        if v_next_partner_name is null then
          v_next_partner_name := 'Cabiniste';
        end if;

        new.assignment_state := 'assigned';
        new.assigned_cabiniste_id := v_next_partner;
        new.assigned_cabiniste_name := v_next_partner_name;
        new.assignment_mode := 'automatic';
        new.assigned_at := now();

        insert into public.phase4_partner_assignment_history(
          order_id,order_reference,partner_id,partner_name,
          mode,status,assigned_by_uid,assigned_at,
          network,amount
        ) values(
          old.order_id,
          old.order_reference,
          v_next_partner,
          v_next_partner_name,
          'automatic',
          'assigned',
          old.assigned_by_uid,
          now(),
          old.network,
          old.amount
        );
      end if;

      new.updated_at := now();
      return new;
    end if;

    if old.assignment_state in ('accepted','handed_off')
       and new.assignment_state=old.assignment_state
       and new.assigned_cabiniste_id
           is not distinct from old.assigned_cabiniste_id
       and new.assigned_cabiniste_name
           is not distinct from old.assigned_cabiniste_name
       and new.assigned_agent_id is null
       and new.assigned_agent_name is null
       and new.assignment_mode
           is not distinct from old.assignment_mode
       and new.assigned_at
           is not distinct from old.assigned_at
       and new.legacy_state_unresolved=false then

      if old.order_status='paidReady'
         and new.order_status='inProgress'
         and new.processing_started_at is not null
         and new.completed_at is null
         and new.failure_reason is null then
        new.updated_at := now();
        return new;
      end if;

      if old.order_status='inProgress'
         and new.order_status='onHold'
         and new.last_hold_reason is not null
         and char_length(btrim(new.last_hold_reason))
             between 3 and 300
         and new.last_held_at is not null then
        new.updated_at := now();
        return new;
      end if;

      if old.order_status='onHold'
         and new.order_status='inProgress'
         and new.last_resumed_at is not null then
        new.updated_at := now();
        return new;
      end if;

      if old.order_status='inProgress'
         and new.order_status='failed'
         and new.completed_at is not null
         and new.failure_reason in (
           'incorrectNumber',
           'networkUnavailable',
           'offerUnavailable',
           'insufficientBalance',
           'technicalError',
           'incorrectPayment',
           'other'
         ) then
        new.updated_at := now();
        return new;
      end if;

      if old.order_status='inProgress'
         and new.order_status='completed'
         and new.completed_at is not null
         and new.failure_reason is null then
        new.updated_at := now();
        return new;
      end if;
    end if;

    raise exception 'INVALID_CABINISTE_ASSIGNMENT_TRANSITION';
  end if;

  if old.assigned_agent_id is distinct from v_uid then
    raise exception 'ASSIGNMENT_OWNER_REQUIRED';
  end if;

  new.order_id := old.order_id;
  new.order_reference := old.order_reference;
  new.network := old.network;
  new.amount := old.amount;
  new.firebase_created_at := old.firebase_created_at;
  new.paid_at := old.paid_at;
  new.created_at := old.created_at;
  new.assigned_by_uid := old.assigned_by_uid;
  new.customer_auth_uid := old.customer_auth_uid;
  new.source := old.source;
  new.client_name := old.client_name;
  new.client_whatsapp_phone := old.client_whatsapp_phone;
  new.beneficiary_phone := old.beneficiary_phone;
  new.operation_type := old.operation_type;
  new.offer_label := old.offer_label;
  new.original_whatsapp_message := old.original_whatsapp_message;
  new.internal_notes := old.internal_notes;
  new.payment_status := old.payment_status;
  new.payment_payer_name := old.payment_payer_name;
  new.payment_reference := old.payment_reference;
  new.payment_confirmed_at := old.payment_confirmed_at;
  new.assigned_cabiniste_id := old.assigned_cabiniste_id;
  new.assigned_cabiniste_name := old.assigned_cabiniste_name;
  new.last_refused_cabiniste_id := old.last_refused_cabiniste_id;

  if old.assignment_state = 'assigned'
     and new.assignment_state = 'accepted' then
    new.assigned_agent_id := old.assigned_agent_id;
    new.assigned_agent_name := old.assigned_agent_name;
    new.assignment_mode := old.assignment_mode;
    new.assigned_at := old.assigned_at;
    new.last_refusal_reason := old.last_refusal_reason;
    new.last_refused_at := old.last_refused_at;
    new.last_refused_agent_id := old.last_refused_agent_id;
    new.firebase_assignment_synced_at := old.firebase_assignment_synced_at;
    new.firebase_handoff_at := old.firebase_handoff_at;
    new.order_status := old.order_status;
    new.processing_started_at := old.processing_started_at;
    new.completed_at := old.completed_at;
    new.failure_reason := old.failure_reason;
    new.observation := old.observation;
    new.last_hold_reason := old.last_hold_reason;
    new.last_held_at := old.last_held_at;
    new.last_resumed_at := old.last_resumed_at;
    new.customer_confirmation_status := old.customer_confirmation_status;
    new.customer_confirmation_completed_at := old.customer_confirmation_completed_at;
    new.legacy_state_unresolved := old.legacy_state_unresolved;
    new.updated_at := now();

    select h.id into v_history_id
    from public.phase4_assignment_history h
    where h.order_id = old.order_id
      and h.agent_id = v_uid
      and h.status = 'assigned'
    order by h.assigned_at desc
    limit 1;

    if v_history_id is not null then
      update public.phase4_assignment_history
      set status = 'accepted',
          accepted_at = now(),
          updated_at = now()
      where id = v_history_id;
    end if;
    return new;
  end if;

  if old.assignment_state = 'assigned'
     and new.assignment_state = 'refused' then
    v_reason := btrim(coalesce(new.last_refusal_reason, ''));
    if char_length(v_reason) < 3
       or char_length(v_reason) > 500 then
      raise exception 'INVALID_REFUSAL_REASON';
    end if;

    select * into v_plan
    from public.phase4_assignment_plans
    where order_id = old.order_id
    for update;

    if not found then
      raise exception 'ASSIGNMENT_PLAN_MISSING';
    end if;

    v_refused := coalesce(
      v_plan.refused_agent_ids,
      '{}'::text[]
    );

    if not (v_uid = any(v_refused)) then
      v_refused := array_append(v_refused, v_uid);
    end if;

    update public.phase4_assignment_plans
    set refused_agent_ids = v_refused,
        updated_at = now()
    where order_id = old.order_id;

    select h.id into v_history_id
    from public.phase4_assignment_history h
    where h.order_id = old.order_id
      and h.agent_id = v_uid
      and h.status in ('assigned','accepted')
    order by h.assigned_at desc
    limit 1;

    if v_history_id is not null then
      update public.phase4_assignment_history
      set status='refused',
          refused_at=now(),
          refusal_reason=v_reason,
          accepted_at=null,
          handed_off_at=null,
          updated_at=now()
      where id=v_history_id;
    end if;

    select candidate_id into v_next_agent
    from unnest(v_plan.candidate_agent_ids)
         with ordinality as c(candidate_id, ord)
    where not (candidate_id = any(v_refused))
      and private.phase3_agent_is_eligible(
        candidate_id,
        old.order_id
      )
    order by ord
    limit 1;

    new.last_refusal_reason := v_reason;
    new.last_refused_at := now();
    new.last_refused_agent_id := v_uid;
    new.firebase_assignment_synced_at := null;
    new.firebase_handoff_at := null;
    new.order_status := 'paidReady';
    new.processing_started_at := null;
    new.completed_at := null;
    new.failure_reason := null;
    new.observation := null;
    new.last_hold_reason := null;
    new.last_held_at := null;
    new.last_resumed_at := null;
    new.customer_confirmation_status := 'pending';
    new.customer_confirmation_completed_at := null;
    new.legacy_state_unresolved := false;

    if v_next_agent is null then
      new.assignment_state := 'manual_required';
      new.assigned_agent_id := null;
      new.assigned_agent_name := null;
      new.assignment_mode := null;
      new.assigned_at := null;
    else
      v_next_name := nullif(
        btrim(coalesce(
          v_plan.candidate_names ->> v_next_agent,
          ''
        )),
        ''
      );

      if v_next_name is null then
        select nullif(btrim(c.agent_name),'')
          into v_next_name
        from public.phase5_agent_capacities c
        where c.agent_id=v_next_agent;
      end if;

      if v_next_name is null then
        v_next_name := 'Agent';
      end if;

      update public.phase4_assignment_plans
      set plan_mode = 'automatic',
          updated_at = now()
      where order_id = old.order_id;

      new.assignment_state := 'assigned';
      new.assigned_agent_id := v_next_agent;
      new.assigned_agent_name := v_next_name;
      new.assignment_mode := 'automatic';
      new.assigned_at := now();

      insert into public.phase4_assignment_history (
        order_id,order_reference,agent_id,agent_name,
        mode,status,assigned_by_uid,assigned_at
      ) values (
        old.order_id,
        old.order_reference,
        v_next_agent,
        v_next_name,
        'automatic',
        'assigned',
        old.assigned_by_uid,
        now()
      );
    end if;

    new.updated_at := now();
    return new;
  end if;

  if old.assignment_state in ('accepted','handed_off')
     and new.assignment_state = old.assignment_state
     and new.assigned_agent_id
         is not distinct from old.assigned_agent_id
     and new.assigned_agent_name
         is not distinct from old.assigned_agent_name
     and new.assignment_mode
         is not distinct from old.assignment_mode
     and new.assigned_at
         is not distinct from old.assigned_at
     and new.last_refusal_reason
         is not distinct from old.last_refusal_reason
     and new.last_refused_at
         is not distinct from old.last_refused_at
     and new.last_refused_agent_id
         is not distinct from old.last_refused_agent_id
     and new.firebase_assignment_synced_at
         is not distinct from old.firebase_assignment_synced_at
     and new.firebase_handoff_at
         is not distinct from old.firebase_handoff_at
     and new.legacy_state_unresolved = false then

    if old.order_status='paidReady'
       and new.order_status='inProgress'
       and new.processing_started_at is not null
       and new.completed_at is null
       and new.failure_reason is null then
      new.updated_at := now();
      return new;
    end if;

    if old.order_status='inProgress'
       and new.order_status='onHold'
       and new.last_hold_reason is not null
       and char_length(btrim(new.last_hold_reason))
           between 3 and 300
       and new.last_held_at is not null then
      new.updated_at := now();
      return new;
    end if;

    if old.order_status='onHold'
       and new.order_status='inProgress'
       and new.last_resumed_at is not null then
      new.updated_at := now();
      return new;
    end if;

    if old.order_status='inProgress'
       and new.order_status='failed'
       and new.completed_at is not null
       and new.failure_reason in (
         'incorrectNumber',
         'networkUnavailable',
         'offerUnavailable',
         'insufficientBalance',
         'technicalError',
         'incorrectPayment',
         'other'
       ) then
      new.updated_at := now();
      return new;
    end if;

    if old.order_status='inProgress'
       and new.order_status='completed'
       and new.completed_at is not null
       and new.failure_reason is null then
      new.updated_at := now();
      return new;
    end if;
  end if;

  if old.assignment_state = 'accepted'
     and new.assignment_state = 'handed_off' then
    new.assigned_agent_id := old.assigned_agent_id;
    new.assigned_agent_name := old.assigned_agent_name;
    new.assignment_mode := old.assignment_mode;
    new.assigned_at := old.assigned_at;
    new.last_refusal_reason := old.last_refusal_reason;
    new.last_refused_at := old.last_refused_at;
    new.last_refused_agent_id := old.last_refused_agent_id;
    new.firebase_assignment_synced_at :=
      coalesce(old.firebase_assignment_synced_at, now());
    new.firebase_handoff_at := now();
    new.updated_at := now();

    select h.id into v_history_id
    from public.phase4_assignment_history h
    where h.order_id=old.order_id
      and h.agent_id=v_uid
      and h.status='accepted'
    order by h.assigned_at desc
    limit 1;

    if v_history_id is not null then
      update public.phase4_assignment_history
      set status='handed_off',
          handed_off_at=now(),
          updated_at=now()
      where id=v_history_id;
    end if;
    return new;
  end if;

  if old.assignment_state='accepted'
     and old.firebase_handoff_at is null
     and new.assignment_state='assigned' then
    new.assigned_agent_id := old.assigned_agent_id;
    new.assigned_agent_name := old.assigned_agent_name;
    new.assignment_mode := old.assignment_mode;
    new.assigned_at := old.assigned_at;
    new.last_refusal_reason := old.last_refusal_reason;
    new.last_refused_at := old.last_refused_at;
    new.last_refused_agent_id := old.last_refused_agent_id;
    new.firebase_assignment_synced_at := old.firebase_assignment_synced_at;
    new.firebase_handoff_at := null;
    new.updated_at := now();

    select h.id into v_history_id
    from public.phase4_assignment_history h
    where h.order_id=old.order_id
      and h.agent_id=v_uid
      and h.status='accepted'
    order by h.assigned_at desc
    limit 1;

    if v_history_id is not null then
      update public.phase4_assignment_history
      set status='assigned',
          accepted_at=null,
          handed_off_at=null,
          updated_at=now()
      where id=v_history_id;
    end if;
    return new;
  end if;

  raise exception 'INVALID_AGENT_ASSIGNMENT_TRANSITION';
end;
$function$

CREATE OR REPLACE FUNCTION private.phase4_agent_action_internal(p_order_id text, p_action text, p_reason text DEFAULT NULL::text)
 RETURNS phase4_assignment_orders
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid text := nullif(btrim(coalesce((select auth.jwt()->>'sub'),'')), '');
  v_row public.phase4_assignment_orders;
begin
  if not public.is_izytel_firebase_jwt() or v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  if p_action='accept' then
    if not private.phase3_agent_is_eligible(v_uid,btrim(p_order_id)) then
      raise exception 'AGENT_NOT_ELIGIBLE_CURRENT_STATE';
    end if;
    update public.phase4_assignment_orders
    set assignment_state='accepted'
    where order_id=btrim(p_order_id)
      and assigned_agent_id=v_uid
      and assignment_state='assigned'
      and order_status='paidReady'
      and legacy_state_unresolved=false
    returning * into v_row;
  elsif p_action='refuse' then
    update public.phase4_assignment_orders
    set assignment_state='refused',last_refusal_reason=p_reason
    where order_id=btrim(p_order_id)
      and assigned_agent_id=v_uid
      and assignment_state='assigned'
      and order_status='paidReady'
      and legacy_state_unresolved=false
    returning * into v_row;
  else
    raise exception 'INVALID_AGENT_ACTION';
  end if;

  if v_row.order_id is null then raise exception 'ASSIGNMENT_NOT_FOUND'; end if;
  return v_row;
end;
